window.CHAR_BIOS = window.CHAR_BIOS || {};

window.CHAR_BIOS['anduin'] = [
  ["A Boy King in Stormwind", [
    "Anduin Llane Wrynn is the son of King Varian Wrynn and Queen Tiffin. He was named for two heroes of Stormwind, his grandfather King Llane and the warrior Anduin Lothar. His mother died in a riot while he was small, and an old servant, Wyll Benton, taught him to read. When he was about ten, his father vanished on the way to peace talks at Theramore, and Anduin was crowned in his place. Highlord Bolvar Fordragon ruled as regent, advised by Lady Katrana Prestor, who was secretly the black dragon Onyxia.",
    "When a Varian came home, Anduin sensed something was wrong with him and said so. He was right. Onyxia's magic had split his father into two men. When she was unmasked she carried Anduin off to her lair, and he hid from her whelps until both Varians arrived. The two halves merged during that fight, and Varian killed the dragon."
  ]],
  ["The Path of the Priest", [
    "Varian wanted a warrior son and sent Anduin to train with the dwarves of Ironforge. There Anduin found his calling as a priest of the Holy Light. He watched King Magni Bronzebeard turn to diamond during a ritual, and he was held hostage when Magni's estranged daughter Moira seized the city. When Varian came to kill her, Anduin talked him out of it. Moira was the lawful heir, he argued, and her death would start a civil war. Varian agreed, and the Council of Three Hammers was born.",
    "Around this time Anduin befriended Baine Bloodhoof, the young tauren chieftain, and gave him the mace Fearbreaker. Against his father's wishes he left to study under Velen, prophet of the draenei. In Pandaria he tried to stop Warchief Garrosh Hellscream from using the Divine Bell, a mogu relic. He turned its power to harmony, and Garrosh smashed the bell down on top of him. Anduin survived, but his bones ached ever after, and he came to treat the pain as a warning when he courted danger or cruelty. While he recovered he struck up a wary friendship with Wrathion, the young black dragon, who thought him too soft. At Garrosh's trial he still kicked away a poisoned meal meant for the prisoner."
  ]],
  ["King of Stormwind", [
    "Varian died at the Broken Shore in Legion, holding off the Burning Legion so his soldiers could escape. Anduin became king as a young man and doubted he deserved it. He walked the Broken Shore in disguise, and when he found his father's sword in the ash, it glowed gold in his hands. He took that as his answer.",
    "Anduin kept reaching for peace. In the novel Before the Storm he arranged the Gathering, a meeting between Forsaken undead and their living families, with help from Calia Menethil, Arthas's lost sister. Sylvanas Windrunner broke it up and killed Calia, and Anduin helped raise her again with the Light. After Sylvanas burned Teldrassil, he led the Alliance against Lordaeron and shielded his wavering army with a dome of Light. He captured Varok Saurfang, then left the orc's cell door open. Saurfang later rose against Sylvanas with Anduin's help, and when the orc died in his duel with her, Anduin helped carry his body into Orgrimmar."
  ]],
  ["Chained by the Jailer", [
    "In Shadowlands, Sylvanas's servants dragged Anduin into the Maw, the prison realm of the Jailer. The Jailer wanted him because his goodness could carry him past the defenses of Bastion. Anduin refused every offer, so Sylvanas forced him into armor of Domination and gave him Kingsmourne, his father's sword reforged around the last scrap of Arthas's soul. Under the Jailer's control he stabbed Kyrestia, the Archon of Bastion, and tore out her sigil. He took two more sigils for his master.",
    "Part of him kept fighting. He hid a message in his father's old compass and dropped it where Jaina Proudmoore would find it. In the Sepulcher of the First Ones, with the heroes' help and a vision of Varian and Saurfang at his side, he broke Kingsmourne in two and freed himself. The last of Arthas faded with it. Afterward Anduin could not face going home. He left Turalyon to rule Stormwind as regent and disappeared."
  ]],
  ["The Wandering King", [
    "For years Anduin worked as a farmhand named Jerek in Stormsong Valley on Kul Tiras. He tried and failed to heal a dying friend there. What haunted him most was a fear that part of him had enjoyed what the Jailer made him do. Thrall found him in Silithus at the start of The War Within, and Anduin went with him to Khaz Algar, where Dalaran fell.",
    "In the vast cavern of Hallowfall, Anduin met the Arathi, humans descended from a lost expedition, and a young soldier named Faerin Lothar, a distant relative of the man he was named for. The Light would not come to him, and he told her he was no longer worthy of it. She did not believe giving up was in his nature. When Khadgar lay dying at the Priory of the Sacred Flame, Anduin reached for the Light and it answered. He later told Thrall he had never lost it. He had only stopped running from it."
  ]],
  ["Midnight", [
    "After Khaz Algar, Anduin came back to Stormwind but did not take back his throne. He fought off demons at the interrupted wedding of Turalyon and Alleria Windrunner. In Midnight he joined the Vanguard of the Light at the Sunwell and spent the siege pouring Light into it. When the Vanguard seized Magister Umbric of the void elves, Anduin stopped them from executing him and took responsibility for him. When Xal'atath turned the Sunwell into the Darkwell, Anduin fell to Void corruption with the other Light-wielders, then recovered in time to see it reborn as the Dawnwell.",
    "Turalyon was lost at the Voidspire, and the games have not said who governs Stormwind now. Anduin admitted to Velen that he had felt broken and unworthy of the future the prophet once saw for him, and that he was beginning to heal. He remains a man who answers cruelty with mercy, even when it costs him."
  ]]
];

window.CHAR_BIOS['jaina'] = [
  ["A Daughter of Kul Tiras", [
    "Jaina Proudmoore was born three years before the First War, the middle child of Lord Admiral Daelin Proudmoore of Kul Tiras and his wife Katherine. She loved books and had a habit of hiding when she was frightened. Her older brother Derek died fighting the Horde at sea in the Second War. When her talent for magic appeared, her mother persuaded Daelin to let her study in Dalaran.",
    "On the way there, eleven-year-old Jaina stayed in Lordaeron's capital, became close friends with Princess Calia Menethil and met Calia's brother, Prince Arthas. In Dalaran she pestered Archmage Antonidas, head of the Kirin Tor, until he took her as his apprentice. He came to believe she could become the greatest sorceress in human history. Prince Kael'thas Sunstrider of the high elves courted her, and she did not return his feelings. She and Arthas fell in love, parted so each could focus on duty, and drew close again when the plague began."
  ]],
  ["Stratholme and the Road West", [
    "Antonidas sent Jaina with Arthas to investigate the plague of undeath. At Stratholme, Arthas ordered the infected townsfolk killed, and Jaina left with Uther the Lightbringer. It ended their romance. A mysterious prophet, later revealed as Medivh, urged her to lead survivors west. When the Scourge came for Dalaran, Antonidas sent her away, and she sailed for Kalimdor with refugees from many kingdoms.",
    "There she clashed with Thrall's orcs until the prophet made them allies. Jaina helped free Grom Hellscream from demonic corruption and fought at the Battle of Mount Hyjal. Out of that war came a friendship with Thrall that shaped the next decade."
  ]],
  ["Lady of Theramore", [
    "Jaina built Theramore, an island city on Kalimdor's coast, and kept the peace with the Horde next door. Then her father sailed in, took over her city and attacked the orcs. Daelin would not listen to her. She helped the Horde break his blockade, and he died fighting them. Jaina knelt by his body and asked why he hadn't listened. Kul Tiras blamed her for his death for many years.",
    "Over the following years Jaina built a career of quiet diplomacy. With the old Guardian Aegwynn, who became her chamberlain, she exposed a demon stirring up war between Theramore and Durotar, and she and Thrall signed a pact of non-aggression. She helped King Varian Wrynn recover his memory, became an honorary aunt to his son Anduin, and secretly funded Baine Bloodhoof's fight to retake Thunder Bluff. In Icecrown Citadel she faced the Lich King and saw there was nothing left of Arthas to save."
  ]],
  ["The Fall of Theramore", [
    "While helping the blue dragon Kalecgos hunt a stolen artifact, the Focusing Iris, Jaina fell in love with him. Garrosh Hellscream, the new Warchief, used that artifact to power a mana bomb and dropped it on Theramore. Rhonin, leader of the Kirin Tor, pushed Jaina through a portal and died in her place. Her hair turned white. When the body of her young apprentice Kinndy crumbled to dust at her touch, Jaina broke.",
    "She took the Iris and summoned a tidal wave to drown Orgrimmar. Thrall held the water back, and Kalecgos reminded her that Arthas had also been sure he was right. Jaina saw what she was becoming and dispelled the wave. She took Rhonin's place at the head of the Kirin Tor, a role Rhonin's old mentor Krasus had foretold in his writings, but grief hardened her. When blood elves of the Sunreavers helped Garrosh steal a relic through Dalaran's portals, she purged them from the city. After Garrosh fell, she urged Varian to dismantle the Horde. Yet at Garrosh's trial, under hard questioning, she said that the Horde was not Garrosh."
  ]],
  ["Exile and Homecoming", [
    "In Legion, Jaina watched Varian die at the Broken Shore after the Horde retreated. When the Kirin Tor voted four to two to let Horde mages back into Dalaran, she left the order, ended things with Kalecgos and fought the demons alone. She confided to him that hate had changed her and she did not know if she could be anything else.",
    "She came back to the fight in Battle for Azeroth at the siege of Lordaeron, where she froze Sylvanas's blight and teleported the trapped Alliance leaders to safety on her ship. Then she went home to win Kul Tiras back for the Alliance. Her mother had her arrested and exiled to Fate's End. In the drust realm of Thros, Jaina relived her worst memories, and Katherine came to understand that Daelin had lost himself to hate. Mother and daughter forgave each other, and Katherine named Jaina Lord Admiral. Jaina brought the Kul Tiran fleet back to the Alliance. When Baine returned her brother Derek, raised from death and freed from Sylvanas's control, Jaina repaid him. She joined Thrall, Saurfang and Mathias Shaw to break Baine out of Sylvanas's prison."
  ]],
  ["Lord Admiral", [
    "In Shadowlands, Jaina was dragged into the Maw with Anduin, Thrall and Baine. She escaped and spent the war fighting to free Anduin from the Jailer. In the Shadowlands she met Uther again, and he told her she could carry her love for Arthas forward without carrying the pain. She said she was one of the few who remembered the prince as well as the monster.",
    "In Dragonflight she reunited with Kalecgos and looked into the Radiant Song, the visions spreading across Azeroth. In The War Within, Xal'atath destroyed Dalaran. Jaina guided the disarming of a mana bomb hidden among its scattered artifacts, promised to destroy the old plans for such bombs, and joined the survivors in vowing to rebuild the Kirin Tor without councils, floating cities or meddling in world affairs. In the Arathi Highlands she helped stop a battle between Stromgarde and the Horde so both could sail for Khaz Algar. As of Midnight she remains Lord Admiral of Kul Tiras. She is brilliant and proud, capable of terrible anger, and has spent much of her life learning to choose mercy anyway."
  ]]
];

window.CHAR_BIOS['varian'] = [
  ["The Prince Who Lost Everything", [
    "Varian Wrynn was born ten years before the First War, the son of King Llane of Stormwind and Queen Taria. He watched Garona murder his father during the orc siege, and his mother was lost as the survivors fled by sea. In Lordaeron, King Terenas treated the boy as an equal and came to see him almost as a second son. Prince Arthas became his closest friend.",
    "Once Stormwind was retaken, Varian was crowned king. He married Tiffin Ellerian, and they had a son, Anduin. Tiffin was killed when the stonemasons who had rebuilt the city rioted over unpaid wages, and Varian sank into a long depression. Lady Katrana Prestor, secretly the black dragon Onyxia, used his grief to cloud his mind and gain power at court."
  ]],
  ["Lo'Gosh", [
    "On the way to peace talks at Theramore, Varian was kidnapped by the Defias Brotherhood. Onyxia's spell to break his will went wrong and split him into two men. One half went home and became her puppet. The other washed up in Durotar with no memory, and an orc trainer made him a gladiator. Fighting beside the night elf Broll Bearmantle and the blood elf Valeera Sanguinar, he won the Crimson Ring tournament and the name Lo'Gosh, Ghost Wolf.",
    "Jaina Proudmoore and Aegwynn helped him remember who he was. He returned to Stormwind, exposed Onyxia and chased her to her lair, where she held Anduin hostage. When she tried to kill one Varian, the other leapt into the spell, and the two halves became one man again. Varian killed Onyxia with Shalamayne, a sword fused from the two elven blades Jaina had given them."
  ]],
  ["The Warrior King", [
    "The reunited Varian was a fierce and angry man. After Bolvar Fordragon fell at the Wrathgate to a Forsaken plague, he stormed the Undercity and declared war on the Horde, and only Jaina's magic stopped a massacre. Yet in Icecrown Citadel he let Varok Saurfang carry away his son's body, out of respect for a grieving father.",
    "In the novel Wolfheart he refused to let Gilneas rejoin the Alliance, calling its people cowards for walling themselves off. Genn Greymane then guided him through a worgen ritual that taught him to master his rage, and Varian emerged as a champion of the wolf spirit Goldrinn. He changed his mind about Gilneas. He also mended things with Anduin, who saved his life with the Light. By the war in Pandaria he led the whole Alliance as High King. After Garrosh fell, Jaina urged him to destroy the Horde. He made peace with its new warchief Vol'jin instead, warning that the Alliance would return if the Horde forgot its honor."
  ]],
  ["The Broken Shore", [
    "In Legion, Varian led the Alliance against the Burning Legion at the Broken Shore. On the way he wrote Anduin a letter admitting that his son's hopes for peace had changed him, and warning that peace sometimes has to be fought for. When the Horde retreated, he ordered his army onto a gunship, and a giant fel reaver grabbed it. Varian handed Genn the letter, let go of the rope ladder and drove his sword into the machine so the ship could escape. Alone among the demons, he answered Gul'dan's mockery with a last cry for the Alliance, and the warlock destroyed him with fel magic.",
    "His empty tomb stands at Lion's Rest in Stormwind. Anduin later saw him in visions sent by the Light, most of all when Varian appeared beside him as he broke free of the Jailer. Where Varian's own soul went has never been shown."
  ]]
];

window.CHAR_BIOS['uther'] = [
  ["First of the Silver Hand", [
    "Uther was a knight of Lordaeron and a devout student of Alonsus Faol, the archbishop who founded the Knights of the Silver Hand during the Second War. Uther became the order's first paladin and its supreme leader. His knights drove back death knights at Hillsbrad, and he fought at Blackrock Spire. Afterward Turalyon gave him the name he kept, the Lightbringer.",
    "In the years of peace he kept order in Lordaeron, settling disputes and putting down uprisings, and while Stormwind was rebuilt he and his paladins cared for the sick and orphaned in its Cathedral of Light. He trained King Terenas's son Arthas, whom he loved like a nephew, and his hope of seeing the prince grow worthy of the crown was the one thing that kept him from retiring. He made Arthas a paladin. He also presided over the trial of his old comrade Tirion Fordring, who had defended an orc. When Tirion would not break his word to the orc, Uther stripped him of his powers and exiled him, though he spared Tirion's wife and son from sharing that exile."
  ]],
  ["Stratholme and Andorhal", [
    "When the plague of undeath swept Lordaeron, Uther rode to rescue Arthas at Hearthglen. At Stratholme, Arthas ordered the infected townsfolk put to the sword. Uther refused, and Arthas called it treason and dismissed him and his paladins. Uther told the king what his son had done, and together they ordered the prince home. Weeks later Arthas came home carrying Frostmourne and killed his father on the throne.",
    "Uther reached the throne room too late to save his king. He cut down the cultists there, consecrated Terenas's body and carried the ashes away in a sacred urn. He made Andorhal his headquarters against the Scourge. Arthas came for the urn. Uther beat him, knocked Frostmourne from his hands and was about to finish him when the Lich King gave Arthas new strength. Bloodied and on his knees, Uther told his old student he hoped a special place in hell was waiting for him. Arthas killed him. His tomb stands in the Western Plaguelands."
  ]],
  ["A Soul Split in Two", [
    "Frostmourne tore Uther's soul apart. One piece stayed trapped in the blade, and in Wrath of the Lich King it warned Jaina and Sylvanas that someone must take the Lich King's place if Arthas fell. That piece was freed when Tirion shattered the sword, and it told the heroes at Icecrown that after so many years of suffering it could finally rest. In Legion, paladins called on his spirit at his tomb, and he told them that Tirion still clung to life. The rest of Uther went to Bastion, the realm of the kyrian in the Shadowlands, where he could not let go of his anger. The kyrian leader Devos let him keep his memories, and when Arthas died, the two of them threw his soul into the Maw instead of bringing it to judgment.",
    "In Shadowlands, Uther joined Devos's rebels, the Forsworn, without knowing that their leaders served the Jailer. When he learned the truth he surrendered. With the heroes' help he relived his life, from his oath as a paladin to his death, and came to regret the anger he had shown Arthas. His example led the kyrian to let every soul choose whether to keep its memories. He then helped wake Sylvanas Windrunner, whose soul had been split the same way, and persuaded Jaina to work with her to save Anduin. He watched the last of Arthas fade and concluded that compassion can save anyone, though it never comes easily."
  ]]
];

window.CHAR_BIOS['tirion'] = [
  ["The Paladin and the Orc", [
    "Tirion Fordring was not born a noble. He was knighted at eighteen for his courage, and Archbishop Alonsus Faol chose him as one of the first five paladins of the Silver Hand. After the Second War he governed Hearthglen as lord of Mardenholde Keep, with his wife Karandra and their son Taelan.",
    "One day he fought an old orc hermit named Eitrigg and was knocked senseless when part of a ruined tower collapsed on him. Eitrigg tied him to his saddle and sent him home instead of killing him. Tirion kept the orc's secret, and when soldiers came to take Eitrigg, he fought them. At his trial he told the truth. Uther stripped him of his paladin powers and exiled him. Tirion freed Eitrigg anyway and found he could still heal the dying orc with the Light. Thrall, the young Warchief, arrived to bring Eitrigg home and never forgot what this human had done."
  ]],
  ["The Highlord", [
    "For years Tirion lived as an outcast in a cottage in the Eastern Plaguelands. His wife told Taelan his father was dead, and Taelan grew up to lead the Scarlet Crusade, a fanatical order of undead hunters. Tirion sent him reminders of their past, and Taelan agreed to leave the Crusade, but its leaders had him killed in front of his father. Over Taelan's body, Tirion vowed to rebuild the true Silver Hand.",
    "When the Lich King's death knights attacked Light's Hope Chapel, Tirion turned the battle. Their commander, Darion Mograine, broke free of the Lich King long enough to hand him the corrupted Ashbringer, and Tirion cleansed the sword and drove Arthas away. He merged the Argent Dawn and the Silver Hand into the Argent Crusade and led it to Northrend, where he asked both Varian and Thrall to accept the freed death knights as allies. Hoping Arthas could still be saved, he once tried to seize the Lich King's frozen heart. When he saw that no trace of Arthas remained, he struck the heart with the Ashbringer instead. He held the Argent Tournament to choose a small strike force, then led it to the Frozen Throne. Arthas froze him in ice and killed his champions, but Tirion broke free and shattered Frostmourne with the Ashbringer. He was ready to put on the Helm of Domination himself until Bolvar Fordragon took the burden instead. Tirion placed the crown on Bolvar's head and kept the truth from everyone but a handful of leaders."
  ]],
  ["Death on the Broken Shore", [
    "After Icecrown, Tirion took Hearthglen back from the Scarlet Crusade and returned to Mardenholde Keep. When the Burning Legion invaded in Legion, his Argent Crusade was first to reach the Broken Shore and was nearly wiped out. Gul'dan used the captured Highlord as bait and dropped him into molten lava. Tirion survived, only to be tortured by a demon jailer. The Argent Crusade freed him, but too late. He chose a new bearer for the Ashbringer, asked them to defeat the Legion and died of his wounds.",
    "He was buried beneath Light's Hope Chapel. Later the new Lich King, Bolvar, ordered death knights to raise him as an undead horseman. The Light itself guarded his tomb, and they failed. Tirion put honor above law his whole life, and Horde and Alliance alike trusted him because of it."
  ]]
];

window.CHAR_BIOS['turalyon'] = [
  ["The Priest Who Became a General", [
    "Turalyon was a noble-born orphan of Lordaeron raised by the Church of the Holy Light. He became a priest who believed in the Light without ever feeling it. Before the Second War he stood beside the orphaned Prince Varian and shamed the quarreling human kings into forming the Alliance. Archbishop Faol made him one of the first paladins of the Silver Hand, and Anduin Lothar chose him as his lieutenant, which only deepened his self-doubt. He fell for the high elf ranger Alleria Windrunner and helped save Quel'Thalas and Lordaeron's capital from the Horde.",
    "At Blackrock Spire, Orgrim Doomhammer shattered Turalyon's shield and killed Lothar in front of him. Turalyon's faith finally broke through as fury. He blazed with Light, knocked Doomhammer senseless with Lothar's broken sword and rallied the army to victory. The moment changed him for good, and from then on guilt and rage were bound up in his Light. He led the rebuilding of Stormwind and helped Varian take its throne."
  ]],
  ["A Thousand Years Away", [
    "Turalyon and Alleria had a son, Arator, and left him as a baby with Alleria's sister Vereesa when they led the Sons of Lothar into Draenor. After the Dark Portal was destroyed from the far side, the two were swept away and presumed dead. The naaru Xe'ra recruited them into the Army of the Light, which fought the Burning Legion across the Twisting Nether. Time ran differently there, and Turalyon lived through about a thousand years of war while roughly two decades passed at home. Xe'ra made him Lightforged and deathless, and he rose to lead her army as High Exarch.",
    "When Alleria began using the Void, Xe'ra imprisoned her, and Turalyon was torn between his faith and the woman he loved. In Legion he finally met his grown son on Argus. When Illidan destroyed Xe'ra, Turalyon tried to cut him down."
  ]],
  ["Regent of Stormwind", [
    "Back on Azeroth, Turalyon brought the Lightforged draenei into the Alliance. At first he loathed his old mentor Faol, now one of the Forsaken, but Faol's blessing won him over. After the Fourth War, Anduin made him Lord Commander and sent him with Alleria to hunt Sylvanas, and their harsh interrogations troubled Jaina. When Anduin was taken in Shadowlands, Turalyon became regent of Stormwind. He governed for years, popular with soldiers and nobles but uneasy with politics.",
    "In the novel Blood Ties, Turalyon gave himself so completely to the Light while trying to save Arator that he nearly turned on his allies, until Alleria called him back. He proposed to her, but demons attacked the wedding. Afterward Alleria admitted she now feared his Light and gave back the ring. They never married."
  ]],
  ["Lost to the Void", [
    "In Midnight, Turalyon led the Vanguard of the Light to defend the Sunwell. He clashed with Lor'themar Theron, the blood elf regent, and refused to believe the Light could do harm even as Light-fed plants called Lightbloom ran wild. At the Amani Pass, in a Light-blinded rage, he struck at the troll Zul'jan, and Arator took the blow. Arator later rebuilt the shield Turalyon had lost when Lothar died and begged him to forgive himself. Turalyon answered that part of him had died with Lothar.",
    "At the Voidspire, some of his own officers turned on Alleria and Arator as tainted by the Void, and Turalyon chose his family. Xal'atath then tore the dark naaru L'ura out of Alleria and used it to turn the Sunwell into the Darkwell. In the blast, Turalyon and Alleria were lost to the Void. Their fate is unknown."
  ]]
];

window.CHAR_BIOS['magni'] = [
  ["The King Under the Mountain", [
    "Magni was the eldest of the three Bronzebeard brothers, with Muradin and Brann, and as a prince he doubted he could be a good king. He led the defense of Ironforge in the Second War and brought his people into the Alliance. He turned the dwarves toward archaeology and helped found the Explorers' League. When Muradin was thought killed by Arthas, Magni poured his grief into forging the Ashbringer, a sword meant to stand against Frostmourne. Years later he found Muradin alive in Northrend and helped him recover his memories.",
    "His hardest failure was his daughter. After Frostmane trolls killed his wife Eimear, Magni trained Moira as a warrior against her nature and made clear he had wanted a son. When the Dark Iron emperor Dagran Thaurissan captured her, Magni sent heroes to kill him and bring her home. Moira refused to come. She had fallen in love with Thaurissan and was carrying his child. Magni insisted she must have been enchanted, yet he never disowned her, and the loss slowly changed him. He began promoting capable women into his own guard. When young Anduin Wrynn came to Ironforge to train, Magni let the boy call him uncle and gave him the mace Fearbreaker."
  ]],
  ["Speaker of Azeroth", [
    "Before the Cataclysm, earthquakes shook Khaz Modan. Magni performed an ancient titan ritual in Old Ironforge, hoping to learn why. It turned him into diamond, fused to the heart of the mountain. Moira seized the city, and the Council of Three Hammers took his place. About four years later Magni woke as a living diamond statue. The world-soul Azeroth had made him her voice. He left the council in place and apologized to Moira for failing her as a father.",
    "As Speaker of Azeroth he revealed in Legion that the planet itself was a titan, and he followed her call to Argus. When Sargeras stabbed the world in Silithus, Magni begged the factions to heal her instead of fighting over her blood, azerite. From the Chamber of Heart, a titan vault deep within the world, he guided the heroes who carried the Heart of Azeroth, mending her wounds and leading the fight against the Old God N'Zoth. He also took Fearbreaker back from Anduin. Through it all he sounded like the same gruff dwarf, but he spoke less of crowns and more of the world's pain."
  ]],
  ["Flesh Again", [
    "By The War Within, years locked in diamond had made Magni bitter, and he resented Azeroth. A ritual to understand the Radiant Song knocked him senseless. In Khaz Algar, a corrupted earthen leader tainted the Awakening Machine, which gives the earthen life. Magni used Azeroth's power to cleanse it and seemed to die doing so. Then his diamond body cracked, and he rose as a dwarf of flesh and blood again. In the same weeks he explored the Ringing Deeps with his grandson Dagran, and the two promised each other that Dagran would be more careful and Magni would try to enjoy an adventure now and then.",
    "He and Moira made their peace. She told him she could not fully forgive him but now understood him, and he told her she would rule with a grace he could only dream of. He refused to take back his hammer Fearbreaker and asked her to keep it. Magni no longer knows whether he is still Azeroth's Speaker. He has gone home to Ironforge with his family and is far gentler than the king who drove his daughter away."
  ]]
];

window.CHAR_BIOS['medivh'] = [
  ["Born with a Demon", [
    "Medivh was the son of Aegwynn, the Guardian of Tirisfal, and the mage Nielas Aran. Aegwynn meant him to inherit her power and sealed it inside him to wake when he came of age. She did not know that Sargeras, lord of the Burning Legion, had hidden his spirit inside her centuries earlier and had passed into her unborn son. Medivh grew up happily near Stormwind's court with his friends Prince Llane Wrynn and Anduin Lothar. At fourteen his power woke all at once. It killed his father and left Medivh in a coma for about ten years, tended by Lothar and the clerics of Northshire.",
    "When he woke, he hid what he was and told the clerics he was in control. He helped Llane and Lothar fight the Gurubashi trolls and, at Llane's plea after King Barathen died, destroyed the troll army with frightening power. Stormwind hailed him as its defender, but the display scared Medivh himself. He went to Karazhan, the tower his mother had built, to learn from her how to master his gifts. There he befriended Moroes, the tower's steward, who urged him to open its doors to guests when dark thoughts crept in."
  ]],
  ["The Guardian Who Opened the Portal", [
    "Sargeras twisted Medivh's thoughts from within. Medivh came to believe Azeroth needed an army, and he made a pact with the orc warlock Gul'dan to open the Dark Portal. When his mother came to Karazhan to confront him, he revealed the truth, killed the blue dragon at her side and banished her. He murdered members of the Council of Tirisfal, the secret order of mages who chose the Guardians, to keep them out of his way. He also had a brief affair with Garona, the half-orc agent of the Horde, and their son Med'an was born later.",
    "His apprentice Khadgar and Garona uncovered his plot, and Lothar led them into Karazhan's depths. Medivh's spell aged Khadgar into an old man, but Khadgar drove a sword into his heart and Lothar cut off his head. He was the first Guardian killed in combat in centuries. Khadgar buried him behind the tower, and the violence of his death cursed the land around Karazhan, which became Deadwind Pass."
  ]],
  ["The Prophet", [
    "Death freed Medivh's spirit from Sargeras. Drifting beyond the world, he saw the plague of undeath coming. Aegwynn spent years gathering the power to call him back, and he returned as a mysterious prophet who could take the shape of a raven. He kept his name hidden, since he would have been known as the sorcerer who brought the orcs. He warned King Terenas and Archmage Antonidas, and both dismissed him. Prince Arthas refused to leave his people. Thrall and Jaina listened. He brought them together on Kalimdor and revealed himself to them and the night elf leaders before the Battle of Mount Hyjal. After the victory he vanished, hoping the races would keep fighting together. In time his own people came to honor him as a hero despite the harm he had done under Sargeras.",
    "In Legion, Medivh appeared at Karazhan to help Khadgar break the Legion's hold on the tower. He told his old apprentice that Azeroth had found its Guardian in him, then flew off as a raven, saying he was needed elsewhere. Echoes of him still haunt Karazhan, and a shade of him spoke with the black dragon Wrathion before the war with N'Zoth. Where Medivh himself is now is unknown."
  ]]
];

window.CHAR_BIOS['khadgar'] = [
  ["Medivh's Apprentice", [
    "Khadgar was a young mage of the Kirin Tor, and Archmage Antonidas argued for sending him as apprentice to Medivh at Karazhan. Dozens before him had been turned away within days. Medivh kept him, and Khadgar slowly saw that his kind, eccentric master was hiding something. With Garona, Gul'dan's half-orc envoy, he discovered that Medivh had opened the Dark Portal. They went to Lothar, who believed them, and together they confronted Medivh in Karazhan. Sargeras, acting through Medivh, drained decades of life from Khadgar, but Khadgar drove a sword into his master's heart. He walked out an old man with white hair and buried Medivh behind the tower.",
    "His magic returned stronger than before. His youth did not."
  ]],
  ["Hero of Two Worlds", [
    "Khadgar went north with Lothar and the refugees and served as the Kirin Tor's liaison to the Alliance. In the Second War he fought beside his friend Turalyon, and afterward he destroyed the Dark Portal and built Nethergarde Keep to watch the rift. When the orcs reopened it, Khadgar went to Draenor with the Sons of Lothar. He tore the Skull of Gul'dan from Deathwing and helped close the portal from the far side. Trapped on the shattered world, he spent the next decades in Outland and brought the naaru to Shattrath City.",
    "Back on Azeroth he joined Dalaran's ruling Council of Six. After Theramore fell, he proposed Jaina Proudmoore as the Kirin Tor's new leader. In Warlords of Draenor he led Horde and Alliance together against the Iron Horde."
  ]],
  ["Leading the Kirin Tor", [
    "In Legion, Khadgar fought Gul'dan inside the Tomb of Sargeras and could not stop him from opening the way for the Burning Legion. He warned the leaders of both factions and called them to Dalaran. In Karazhan a vision of Medivh offered him the power of a Guardian. Khadgar admitted he wanted it and refused for that very reason, and the vision turned out to be a dreadlord. He then persuaded the Council of Six to let Horde mages back into the Kirin Tor. Jaina left in protest, and Khadgar led Dalaran through the war. The real Medivh later told him he was already Azeroth's Guardian through his own courage and will. At the Nighthold, Khadgar used the naaru relic Light's Heart to return Illidan's soul to his body, and on Argus he finally reunited with Turalyon and Alleria, whom he had searched for in vain after Draenor's fall."
  ]],
  ["After Dalaran", [
    "Weary after the Legion war, Khadgar refused to fight in the war over azerite and went to Karazhan to look for ways to heal the world. He later visited the Shadowlands and, in Dragonflight, helped Kalecgos defend the Azure Span. He sent Alleria Windrunner to find the mysterious Harbinger, who proved to be Xal'atath.",
    "In The War Within, Xal'atath lured Dalaran to Khaz Algar and destroyed it. Khadgar turned himself into pure arcane energy and let her pull him into her relic, the Dark Heart, trusting Alleria to free him. She did. He came out near death and Anduin healed him, but the spell left him using an arcane wheelchair. With Dalaran gone, the Kirin Tor broke up, and its survivors pledged to rebuild it humbler, without councils or floating cities. Khadgar stood as Turalyon's best man at the wedding that demons cut short. By Midnight he had recovered in Dornogal and was back at the Arcantina, the hidden inn he once found for the Sons of Lothar. He is curious and loyal, and always willing to work with the Horde when the world is at stake."
  ]]
];

window.CHAR_BIOS['llane'] = [
  ["Prince, King and Friend", [
    "Llane Wrynn was the son of King Barathen of Stormwind and grew up with two close friends, the young mage Medivh and the warrior Anduin Lothar. When he came of age, Medivh gave him an enchanted hourglass whose sand never ran out, a promise of Stormwind's lasting prosperity. When Gurubashi trolls massacred villages in Westfall, the three friends went south to strike back against King Barathen's wishes and killed a troll warlord empowered by the blood god Hakkar. The trolls answered with an invasion, and Barathen died leading a desperate charge. Guilt-stricken, Llane begged Medivh to unleash his power, and Medivh destroyed the troll army. Llane became king.",
    "He had a son, Varian, and taught him to ride and fight. When green-skinned raiders came out of the Black Morass, Llane sent Lothar to investigate and named him King's Champion. The other human kingdoms ignored his pleas for help. Llane was proud and sure of his city, and he refused to carry the war into orc lands. He also refused to believe that Medivh had brought the orcs, even when Aegwynn, Medivh's mother, warned him, and again when Khadgar and Garona brought proof.",
    "After Medivh died, Garona, a half-orc who had come over to Stormwind, became Llane's trusted adviser and friend. But the Shadow Council had planted commands in her mind. During the second orc siege of Stormwind, Llane directed the defense from Stormwind Keep as the orcs fought through the streets. There Garona killed him, and his son Varian saw it happen. She had foreseen the deed in a vision and grieved him more than anyone. The city fell soon after. Llane's grandson Anduin carries his name."
  ]]
];

window.CHAR_BIOS['lothar'] = [
  ["The Lion of Azeroth", [
    "Anduin Lothar was one of the last descendants of the Arathi kings who founded Arathor, humanity's first empire. He grew up at Stormwind's court as a friend of Prince Llane and Medivh and rose high in Stormwind's army. In the First War, Llane named him King's Champion. Lothar ambushed orc raiding parties, nearly killed Warchief Blackhand near Lakeshire and saved Stormwind City by sailing his knights around the besieging Horde to strike it from behind.",
    "When Khadgar told him Medivh had brought the orcs, Lothar believed him over the king. He led the attack on Karazhan and cut off his old friend's head. He came back to find Llane dead and Stormwind lost. He declared the war over and led the survivors north to Lordaeron, acting as regent for young Varian.",
    "His warnings moved King Terenas to found the Alliance of Lordaeron. Because he served no northern king and carried the blood of Arathor, Lothar was named Supreme Commander. His shield flashing through the orc ranks earned him the name Lion of Azeroth, and he chose the young paladin Turalyon as his lieutenant. At Blackrock Spire, near the war's end, he was cut off from his troops and fell in single combat with Orgrim Doomhammer, who shattered his sword. Turalyon took up the broken blade and won the war.",
    "A statue of Lothar's last charge stands in the Burning Steppes. The veterans who invaded Draenor called themselves the Sons of Lothar, and Varian named his son after him. In The War Within, Anduin met Faerin Lothar in Hallowfall, a distant relative among the Arathi who had left the Eastern Kingdoms long ago."
  ]]
];

window.CHAR_BIOS['daelin'] = [
  ["The Admiral Who Could Not Forgive", [
    "Daelin Proudmoore ruled the island kingdom of Kul Tiras as Lord Admiral. When the Alliance of Lordaeron formed, he wanted overall command, but it went to his old friend Anduin Lothar, and Daelin became Grand Admiral of the Alliance navy. Kul Tiras paid for much of its fleet. Near Zul'Dare he almost sank the Horde's invasion fleet until enslaved red dragons drove him back. Later he crushed the Horde fleet at Crestfall, but his eldest son Derek died in the battle. The loss haunted him and fed a hatred of orcs for the rest of his life.",
    "After the war he stood with King Terenas through the Alliance's quarrels and sat on the jury at Tirion Fordring's trial. After Lordaeron fell, he sailed to Kalimdor to find his daughter Jaina and destroy Thrall's new Horde before it took root. He raided orc lands, took over Jaina's city of Theramore and ordered her Horde friends arrested. Jaina saw that her father was trapped in the past and helped the Horde break his blockade. Thrall told Daelin that this Horde was different. Daelin did not believe it and died fighting the Horde's champion, Rexxar.",
    "His people cried out for vengeance, but the rest of the Alliance had little sympathy for his war. Kul Tiras turned its anger on Jaina and cut itself off from the Alliance, and his widow Katherine became Lord Admiral. His grave lies at Lord Admiral's Rest in Boralus. In the short Warbringers: Jaina, she speaks to his spirit and tells him she is listening now, and in Battle for Azeroth her mother finally saw that hatred had consumed him."
  ]]
];

window.CHAR_BIOS['terenas'] = [
  ["The King Who Built the Alliance", [
    "Terenas Menethil II ruled Lordaeron, the strongest human kingdom, for about fifty years. When Anduin Lothar brought Stormwind's refugees north, Terenas called the human rulers together and forged the Alliance of Lordaeron. He backed Lothar as Supreme Commander and took young Prince Varian into his household, loving him almost as a second son. During the Second War he stood on his capital's walls himself, though he was no warrior.",
    "After the victory he argued for mercy. The captured orcs went into internment camps paid for by a new tax, and he kept Orgrim Doomhammer as his prisoner, hoping for a treaty. The cost of the camps and the quarrel over traitorous Alterac split the Alliance, and Gilneas, Stromgarde and Quel'Thalas left it. Under the influence of Lord Daval Prestor, secretly the black dragon Deathwing, he even planned to marry his daughter Calia to him.",
    "As the plague spread, Terenas refused calls for a quarantine and dismissed a mysterious prophet who begged him to lead his people west. After his son Arthas purged Stratholme, Terenas ordered him home from Northrend. Arthas returned to a celebration, knelt before the throne and drove Frostmourne through his father's heart. Uther kept the king's ashes in an urn, but Arthas later took it and scattered them.",
    "Terenas's spirit was trapped in Frostmourne. When Tirion shattered the blade at Icecrown, Terenas raised the fallen heroes to finish the Lich King, stayed with his dying son and warned Tirion that there must always be a Lich King. His people had loved him as a wise and just ruler. His daughter Calia survives, now one of the undead."
  ]]
];

window.CHAR_BIOS['calia'] = [
  ["The Hidden Princess", [
    "Calia Menethil is the elder child of King Terenas and Queen Lianne, two years older than Arthas. Because Arthas was the heir, no one taught her to rule. Her father once planned to marry her to Lord Prestor, who was secretly Deathwing. Calia instead secretly married a Lordaeron footman and had a daughter, who was raised away from court.",
    "Everyone believed she died when Arthas murdered their father. She hid from the Scourge, found her husband and daughter in Southshore, then lost them again when the town fled the plague. She never learned what became of them. Meeting Alonsus Faol, the old archbishop now raised as one of the Forsaken, taught her that free-willed undead were still people, and she became a priest of his Conclave."
  ]],
  ["The Pallid Lady", [
    "In the novel Before the Storm she helped Anduin Wrynn arrange the Gathering of Forsaken and their living families, hoping to find her own. When she revealed herself and urged the Forsaken to join the Alliance, Sylvanas Windrunner killed her. Anduin, Faol and the naaru Saa'ra raised her as an undead filled with the Light. She grew close to Jaina's brother Derek Proudmoore, who had also been raised from death, and after Sylvanas abandoned the Horde, Calia went to help the Forsaken.",
    "After the Shadowlands war she helped clear the plague from the ruins of Lordaeron and joined the new Desolate Council that rules the Forsaken, saying she wanted no throne. Calling herself the Pallid Lady, she pushed for the Forsaken to leave Gilneas and then helped the Gilneans retake it. In Midnight she stood among the Light-wielders defending the Sunwell. Because the Forsaken are part of the Horde, Calia now serves on the Horde side."
  ]]
];

window.CHAR_BIOS['arator'] = [
  ["Son of Two Worlds", [
    "Arator is the half-elf son of Alleria Windrunner and Turalyon. His parents left him as a baby with Alleria's sister Vereesa before they went to Draenor, and they did not come back. Vereesa and her husband Rhonin raised him, Lor'themar Theron trained him as a Farstrider ranger, and he grew up feeling neither human nor elf enough to belong. He became a paladin of the Silver Hand to follow his father's path and was knighted as the Redeemer. He searched Outland for his parents without success and finally met them on Argus during Legion, where he asked them why they had never come home. Becoming a family with people he knew only from legends proved hard. In The War Within he even entered the Maw to ask his aunt Sylvanas to defend Quel'Thalas, and she refused."
  ]],
  ["The Light and the Void", [
    "Midnight tested him. At the Sunwell the Light burst out of him in wrath, leaving embers burning on his armor. At the Amani Pass his father struck at a troll in a Light-blinded rage, and Arator took the blow. He traveled with Faol to learn gentler paths of the Light, rebuilt the shield Turalyon had lost when Lothar died, and took it up himself when his father would not. In the Voidstorm he fought beside his mother. At the Voidspire his parents were lost to the Void, and Magister Umbric teleported him to safety.",
    "Arator then called every elven people to retake the Sunwell, fought L'ura with Vereesa and saw the well reborn as the Dawnwell. Grieving, he now works with Umbric against the Twilight's Blade and has started learning to handle the Void himself. He is compassionate, stubborn and quick to see the best in others."
  ]]
];

window.CHAR_BIOS['genn'] = [
  ["The King Behind the Wall", [
    "Genn Greymane ruled Gilneas, a proud kingdom that trusted no one. He joined the Alliance of Lordaeron grudgingly and resented paying for orc camps after the war. When Thrall freed the orcs, Genn left the Alliance and built the Greymane Wall to seal his kingdom off. In the Third War he secretly had the archmage Arugal summon worgen against the Scourge. The wolf-men turned on his own people, and their curse spread through Gilneas. A worgen bit Genn himself, and he hid it for years.",
    "In Cataclysm the Forsaken invaded. Genn united his people by revealing his curse and fought to retake his capital, but an arrow Sylvanas Windrunner meant for him killed his son Liam. The Gilneans fled to the night elves, and Genn admitted that walling off his kingdom had been a mistake. Varian Wrynn at first rejected Gilneas, until Genn helped him master his own rage and won his friendship."
  ]],
  ["Old Wolf of the Alliance", [
    "Genn became a fierce voice at the Alliance's side and later Anduin's adviser. After Varian died at the Broken Shore, he swore vengeance on the Forsaken and fought Sylvanas in Stormheim. When Anduin was taken to the Shadowlands, Genn watched helplessly, and afterward he told the young king he was the strongest man he knew.",
    "In Dragonflight he went home at last. He could not bear to work with the Forsaken who came to help, so he gave command to his daughter Tess. After Gilneas was retaken, he admitted she had proven herself and abdicated in her favor. He later ruled Stormwind while Turalyon fought in Khaz Algar. Genn is stubborn and slow to forgive, but he has learned."
  ]]
];

window.CHAR_BIOS['moira'] = [
  ["Princess of Ironforge, Queen of the Dark Irons", [
    "Moira Bronzebeard was Magni's only child. After her mother died, Magni drilled her as a warrior and made clear he had wanted a son, and the two grew apart. While leading guards to help Lakeshire, she was captured by the Dark Iron dwarves and taken to their emperor, Dagran Thaurissan. They fell in love. Magni sent heroes to kill Thaurissan and fetch her, but Moira refused to come home. She was pregnant with the emperor's heir.",
    "Ruling the Dark Irons, she quietly steered adventurers against Ragnaros and the Dark Horde, the enslavers and rivals of her people. When Magni turned to diamond, she marched into Ironforge with her infant son, Dagran II, and held the city hostage, Prince Anduin included. Varian Wrynn came to kill her. Anduin convinced him her death would start a civil war, so Varian made her share power on the Council of Three Hammers with Muradin and Falstad Wildhammer."
  ]],
  ["Earning Her Seat", [
    "Moira earned her place. When trolls threatened Ironforge in Mists of Pandaria, she alone marched out with Varian while the others feared leaving the city to her. She later made the Dark Irons' membership in the Alliance official.",
    "In The War Within she sat at her stricken father's side in Dalaran, survived its fall in Khaz Algar and helped the earthen reunite. She watched Magni seem to die cleansing the Awakening Machine and come back as flesh. She told him she could not fully forgive him but now understood him, and he left his hammer Fearbreaker with her. In Midnight she channeled the Light into the Sunwell. She is shrewd, proud and fiercely protective of her son."
  ]]
];

window.CHAR_BIOS['muradin'] = [
  ["The Brother Who Came Back", [
    "Muradin Bronzebeard is the middle of the three Bronzebeard brothers, between King Magni and the explorer Brann. He fought in the Second War and then served as Ironforge's ambassador to Lordaeron, where he befriended young Prince Arthas and taught him swordplay. He helped found the Explorers' League and loved the frozen north.",
    "In the Third War, Muradin was hunting the runeblade Frostmourne in Northrend when Arthas arrived chasing the dreadlord Mal'Ganis. Muradin was troubled by how the prince had changed. When they found the sword, Muradin read its curse aloud and begged him to leave it. The ice shattered, and a shard struck Muradin down. Everyone believed him dead, and Magni forged the Ashbringer in his memory.",
    "He had survived without his memory. The Frostborn dwarves of the Storm Peaks took him in and made him their king under the name Yorg Stormheart. In Wrath of the Lich King his brothers found him and helped him remember. The Frostborn joined the Alliance, though as their king he worried about dragging them into wars that would get them killed. He left them to hunt Arthas and commanded the Alliance gunship Skybreaker in the assault on Icecrown Citadel.",
    "After Magni became diamond, Muradin took the Bronzebeard seat on the Council of Three Hammers. He distrusted his niece Moira until her courage in Pandaria shamed him and Falstad. He still sits on the council and said he was open to peace with the Horde once Sylvanas was gone. In recent years he traveled Northrend with Magni and Brann, pushed Moira to bring her son Dagran into the council's work, and showed an envoy of the earthen of Khaz Algar around Ironforge. He is warm, blunt and loyal, and he still speaks fondly of the boy Arthas once was."
  ]]
];

window.CHAR_BIOS['aegwynn'] = [
  ["The Last Great Guardian", [
    "Aegwynn was the only girl among five apprentices of the Guardian Magna Scavell, and she outshone the boys who mocked her. The Council of Tirisfal, the secret order that chose and empowered the Guardians, picked her to succeed him. She was bold and impatient with the council's caution. About eight centuries before the First War she fought an avatar of Sargeras in Northrend with the help of dragons and destroyed it. She sealed its body in a sunken temple that became the Tomb of Sargeras, never knowing his spirit had slipped into her.",
    "Proud of her victory, she refused to give up her power. For centuries she defied the council, built the tower of Karazhan and hid from the mages sent to bring her in. One of them, Nielas Aran, became her lover. She bore their son Medivh and sealed her power within him so the council could not choose her successor, and Sargeras passed into him as well.",
    "When Medivh opened the Dark Portal, she confronted him in Karazhan and learned the truth. He banished her, and she failed to convince King Llane of the danger. Living alone in Kalimdor, she saved her strength for years to bring Medivh's spirit back, and he returned as the Prophet. She later saved Jaina Proudmoore's life against a demon and became her chamberlain at Theramore. She helped Varian Wrynn recover his memory and found her grandson Med'an, Medivh's son by Garona. Aegwynn died giving Med'an the power to defeat the ogre mage Cho'gall and was buried beside her son. An echo she left in the Tomb of Sargeras guided heroes in Legion."
  ]]
];

window.CHAR_BIOS['antonidas'] = [
  ["Grand Magus of Dalaran", [
    "Antonidas was a prodigy who won the Kirin Tor's highest honor for a thesis on time magic at twelve and rose to lead the Kirin Tor, the mages who ruled Dalaran. He argued for sending young Khadgar to Medivh, and later made him an archmage and put him in charge of the expedition to Draenor. In the Second War he pledged Dalaran to the Alliance of Lordaeron. Afterward he studied the strange lethargy of the captive orcs and concluded it was withdrawal from demonic magic that only a spiritual cure could heal.",
    "When the council member Kel'Thuzad turned to necromancy, Antonidas threatened him with exile, and Kel'Thuzad left to serve the Lich King. Antonidas also sat on the jury that exiled Tirion Fordring. His favorite pupil was Jaina Proudmoore, whom he hoped would succeed him. Old and in failing health, he grew cautious. When the Prophet urged him to take his people west, Antonidas called him a madman. He studied the plague and pleaded for a quarantine, but no one listened.",
    "When Arthas and the Scourge came for the spellbook of Medivh, Antonidas sent Jaina away and stayed to defend his city. He made a last stand, and with his dying words he told Arthas it pained him to see the prince fall so far. Kel'Thuzad used the book to summon Archimonde, who crushed Dalaran. Antonidas's ghost fought on in the ruins until Kael'thas set it free.",
    "Jaina raised a memorial to him in the rebuilt Dalaran. A warning he had left on a dangerous tome later helped stop her from drowning Orgrimmar, and after Dalaran was destroyed again, she recovered his primer on magic."
  ]]
];

window.CHAR_BIOS['rhonin'] = [
  ["The Reckless Archmage", [
    "Rhonin was a gifted and reckless mage of the Kirin Tor who came from a family without magic and broke with them to study it. During the Second War one of his spells killed his own comrades, and he was put on probation. His chance at redemption was a near-hopeless mission into Horde-held Khaz Modan, set up by the dragon mage Krasus, secretly the red dragon Korialstrasz. With the ranger Vereesa Windrunner and the gryphon rider Falstad, he freed the Dragonqueen Alexstrasza from the Dragonmaw clan by destroying the Demon Soul that held her. He and Vereesa fell in love and married, and they raised her nephew Arator.",
    "Later Krasus pulled him ten thousand years into the past to the War of the Ancients, where he fought beside Malfurion, Tyrande and Illidan. The bronze dragon Nozdormu returned him at the moment Vereesa went into labor with their twin sons.",
    "After the Third War, the desperate Kirin Tor asked Rhonin to lead them. He moved Dalaran to Northrend, led the war on the mad blue dragon Malygos and tried, without success, to unite Horde and Alliance against the Old God Yogg-Saron. When Garrosh Hellscream attacked Theramore, Rhonin came to defend it. As the mana bomb fell, he drew the blast into Jaina Proudmoore's warded tower to contain it, told her she was the future of the Kirin Tor and pushed her through a portal. He died in the explosion. Jaina succeeded him, as Krasus had foreseen. Vereesa tried to poison Garrosh in revenge, and in The War Within she cast Rhonin's anniversary locket into the sea in his memory."
  ]]
];
